CREATE TABLE IF NOT EXISTS hr_access (id serial PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id),user_id integer NOT NULL REFERENCES users(id),granted_by integer NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS hr_access_member ON hr_access(tenant_id,user_id);
CREATE TABLE IF NOT EXISTS hr_settings (tenant_id integer PRIMARY KEY REFERENCES tenants(id),public_hiring_enabled boolean NOT NULL DEFAULT false,application_intro text NOT NULL DEFAULT '',privacy_notice text NOT NULL DEFAULT 'Your application is stored for recruitment and hiring contact. Contact the employer with privacy questions.',application_fields jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS employee_profiles (id serial PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id),user_id integer NOT NULL REFERENCES users(id),legal_name text,phone text,personal_email text,address text,job_title text,department text,hire_date text,end_date text,employment_status text NOT NULL DEFAULT 'active',emergency_contact_name text,emergency_contact_phone text,notes text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS employee_profile_member ON employee_profiles(tenant_id,user_id);
CREATE TABLE IF NOT EXISTS hr_postings (id serial PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id),title text NOT NULL,description text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'open',fields jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hr_applications (id serial PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id),posting_id integer REFERENCES hr_postings(id),request_id text NOT NULL,payload_hash text NOT NULL,full_name text NOT NULL,email text NOT NULL,phone text NOT NULL,stage text NOT NULL DEFAULT 'applied',source text NOT NULL,notes text,answers jsonb NOT NULL DEFAULT '{}',field_snapshot jsonb NOT NULL DEFAULT '[]',consent_at timestamptz,consent_snapshot text,user_id integer REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS hr_application_request ON hr_applications(tenant_id,request_id);
ALTER TABLE hr_applications ADD COLUMN IF NOT EXISTS pending_account_setup boolean NOT NULL DEFAULT false;
ALTER TABLE employee_history_entries ADD COLUMN IF NOT EXISTS shared_with_employee boolean NOT NULL DEFAULT false;
ALTER TABLE employee_history_entries ADD COLUMN IF NOT EXISTS occurred_on text;
ALTER TABLE employee_history_entries ADD COLUMN IF NOT EXISTS form_snapshot jsonb;
ALTER TABLE employee_history_entries ADD COLUMN IF NOT EXISTS evidence jsonb;
ALTER TABLE employee_history_entries ADD COLUMN IF NOT EXISTS acknowledged_at timestamptz;
CREATE TABLE IF NOT EXISTS hr_documents (id serial PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id),employee_id integer REFERENCES users(id),application_id integer REFERENCES hr_applications(id),history_entry_id integer REFERENCES employee_history_entries(id),title text NOT NULL,file_name text NOT NULL,mime_type text NOT NULL,size_bytes integer NOT NULL,object_path text NOT NULL,shared_with_employee boolean NOT NULL DEFAULT false,uploaded_by integer REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK ((employee_id IS NOT NULL)::integer+(application_id IS NOT NULL)::integer=1));
CREATE TABLE IF NOT EXISTS employee_form_assignments (id serial PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id),user_id integer NOT NULL REFERENCES users(id),template_id integer NOT NULL REFERENCES employee_form_templates(id),title text NOT NULL,snapshot jsonb NOT NULL,required boolean NOT NULL DEFAULT true,due_date text,answers jsonb NOT NULL DEFAULT '{}',submitted_at timestamptz,submitted_by integer REFERENCES users(id),assigned_by integer NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hr_audit (id serial PRIMARY KEY,tenant_id integer NOT NULL REFERENCES tenants(id),actor_id integer REFERENCES users(id),employee_id integer REFERENCES users(id),application_id integer REFERENCES hr_applications(id),action text NOT NULL,"before" jsonb,"after" jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS hr_audit_employee ON hr_audit(tenant_id,employee_id,id);
CREATE INDEX IF NOT EXISTS hr_documents_employee ON hr_documents(tenant_id,employee_id);
CREATE INDEX IF NOT EXISTS hr_applications_stage ON hr_applications(tenant_id,stage);
